  "implementation": "def solve(case):
    word_token_indices = case['word_token_indices']
    word_labels = case['word_labels']
    token_count = case['token_count']

    # Validate word_labels length
    if len(word_token_indices) != len(word_labels):
        raise ValueError('Mismatch between word_token_indices and word_labels lengths')

    # Initialize token_labels array
    token_labels = [None] * token_count

    for word_idx, indices in enumerate(word_token_indices):
        label = word_labels[word_idx]
        for idx in indices:
            if not (0 <= idx < token_count):
                raise ValueError(f'Token index {idx} out of range [0, {token_count-1}]')
            if token_labels[idx] is not None:
                raise ValueError(f'Overlapping token index {idx}')
            token_labels[idx] = label

    # Check all tokens covered
    for i, lbl in enumerate(token_labels):
        if lbl is None:
            raise ValueError(f'Token index {i} is not covered by any word')

    kept_indices = [i for i, lbl in enumerate(token_labels) if lbl == 1]
    return {'kept_indices': kept_indices, 'token_labels': token_labels}"
}
